import React, { useState, useRef } from "react";
import {
  View,
  Text,
  FlatList,
  Image,
  StyleSheet,
  TouchableOpacity,
  Dimensions,
  TextInput,
  Keyboard,
  Animated,
  ImageBackground,
} from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";
import { useRouter } from "expo-router";
import MapView, { Marker, AnimatedRegion } from "react-native-maps";
import { BlurView } from "expo-blur";

const { width } = Dimensions.get("window");
const CARD_WIDTH = width * 0.85;
const DEFAULT_IMAGE =
  "https://images.unsplash.com/photo-1501117716987-c8e1ecb2106b";

// 13 Indian cities with images and coordinates
const hotelsData = [
  { id: "1", name: "Delhi Grand", city: "Delhi", outerImage: "https://images.unsplash.com/photo-1566073771259-6a8506099945?fit=crop&w=800&q=80", coordinates: { latitude: 28.6139, longitude: 77.209 } },
  { id: "2", name: "Mumbai Elite", city: "Mumbai", outerImage: "https://images.unsplash.com/photo-1578683010236-d716f9a3f461?fit=crop&w=800&q=80", coordinates: { latitude: 19.076, longitude: 72.8777 } },
  { id: "3", name: "Bangalore Heights", city: "Bangalore", outerImage: "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTDzJJIFNTRmEZqi4eSLMAw_JGmqxk74fggSg&s", coordinates: { latitude: 12.9716, longitude: 77.5946 } },
  { id: "4", name: "Chennai Palace", city: "Chennai", outerImage: "https://images.trvl-media.com/lodging/1000000/20000/19400/19313/84750a2b.jpg?impolicy=fcrop&w=357&h=201&p=1&q=medium", coordinates: { latitude: 13.0827, longitude: 80.2707 } },
  { id: "5", name: "Kolkata Royale", city: "Kolkata", outerImage: "https://dynamic-media-cdn.tripadvisor.com/media/photo-o/17/a2/4e/0e/hotel-facade.jpg?w=1200&h=-1&s=1", coordinates: { latitude: 22.5726, longitude: 88.3639 } },
  { id: "6", name: "Hyderabad Grandeur", city: "Hyderabad", outerImage: "https://dynamic-media-cdn.tripadvisor.com/media/photo-o/16/0d/31/3c/the-golkonda-hyderabad.jpg?w=1200&h=-1&s=1", coordinates: { latitude: 17.385, longitude: 78.4867 } },
  { id: "7", name: "Pune Regency", city: "Pune", outerImage: "https://ik.imgkit.net/3vlqs5axxjf/external/ik-seo/https://www.cfmedia.vfmleonardo.com/imageRepo/2/0/67/895/621/FACADE_MALL_164_main_light_option_O/Vivanta-Pune-Hinjawadi-Exterior.jpg?tr=w-656%2Ch-390%2Cfo-auto", coordinates: { latitude: 18.5204, longitude: 73.8567 } },
  { id: "8", name: "Ahmedabad Comfort", city: "Ahmedabad", outerImage: "https://www.itchotels.com/content/dam/itchotels/in/umbrella/itc/hotels/itcnarmada-ahmedabad/images/overview-landing-page/headmast/desktop/itc-narmada.jpg", coordinates: { latitude: 23.0225, longitude: 72.5714 } },
  { id: "9", name: "Jaipur Royal", city: "Jaipur", outerImage: "data:image/jpeg;base64,", coordinates: { latitude: 26.9124, longitude: 75.7873 } },
  { id: "10", name: "Lucknow Heritage", city: "Lucknow", outerImage: "data:image/jpeg;base64,", coordinates: { latitude: 26.8467, longitude: 80.9462 } },
  { id: "11", name: "Kochi Riverside", city: "Kochi", outerImage: "data:image/jpeg;base64,", coordinates: { latitude: 9.9312, longitude: 76.2673 } },
  { id: "12", name: "Indore Palace", city: "Indore", outerImage: "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSspl4x54wYkCsfPrkkY6cmYMWIPHw34J73xg&s", coordinates: { latitude: 22.7196, longitude: 75.8577 } },
  { id: "13", name: "Bhopal Serenity", city: "Bhopal", outerImage: "data:image/jpeg;base64,", coordinates: { latitude: 23.2599, longitude: 77.4126 } },
];

const AnimatedMapView = Animated.createAnimatedComponent(MapView);

export default function HomeScreen() {
  const router = useRouter();
  const [searchCity, setSearchCity] = useState("");
  const [mapRegion, setMapRegion] = useState(
    new AnimatedRegion({
      latitude: 28.6139,
      longitude: 77.209,
      latitudeDelta: 0.5,
      longitudeDelta: 0.5,
    })
  );
  const scrollX = useRef(new Animated.Value(0)).current;

  const handleSearch = async () => {
    Keyboard.dismiss();
    if (!searchCity) return;

    try {
      const response = await fetch(
        `https://nominatim.openstreetmap.org/search?city=${searchCity}&format=json&limit=1`
      );
      const data = await response.json();
      if (data && data.length > 0) {
        const { lat, lon } = data[0];
        mapRegion.timing({
          latitude: parseFloat(lat),
          longitude: parseFloat(lon),
          latitudeDelta: 0.5,
          longitudeDelta: 0.5,
          duration: 1000,
        }).start();
      }
    } catch (err) {
      console.log("Error fetching city coordinates:", err);
    }
  };

  const filteredHotels = hotelsData.filter((hotel) =>
    hotel.city.toLowerCase().includes(searchCity.toLowerCase())
  );

  const handlePress = (hotel) => {
    router.push({ pathname: "/HotelList", params: { city: hotel.city } });
  };

  const HotelCard = ({ item, index }) => {
    const inputRange = [
      (index - 1) * CARD_WIDTH,
      index * CARD_WIDTH,
      (index + 1) * CARD_WIDTH,
    ];
    const scale = scrollX.interpolate({
      inputRange,
      outputRange: [0.85, 1, 0.85],
      extrapolate: "clamp",
    });
    const rotateY = scrollX.interpolate({
      inputRange,
      outputRange: ["15deg", "0deg", "-15deg"],
      extrapolate: "clamp",
    });

    return (
      <Animated.View
        style={[styles.card, { transform: [{ scale }, { perspective: 1000 }, { rotateY }] }]}
      >
        <TouchableOpacity style={{ flex: 1 }} onPress={() => handlePress(item)} activeOpacity={0.9}>
          <Image source={{ uri: item.outerImage || DEFAULT_IMAGE }} style={styles.image} resizeMode="cover" />
          <BlurView intensity={80} tint="dark" style={styles.hotelNameOverlay}>
            <Text style={styles.hotelName}>{item.name}</Text>
          </BlurView>
        </TouchableOpacity>
      </Animated.View>
    );
  };

  return (
    <ImageBackground
      source={{ uri: "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSt_-YM7QzIFmHMR2GQAWOrcSKyIu38t4bLYA&s" }}
      style={{ flex: 1 }}
    >
      <SafeAreaView style={{ flex: 1, backgroundColor: "rgba(0,0,0,0.3)" }}>
        <View style={styles.searchContainer}>
          <BlurView intensity={70} tint="light" style={styles.searchInputWrapper}>
            <TextInput
              placeholder="Search your city"
              placeholderTextColor="#ccc"
              value={searchCity}
              onChangeText={setSearchCity}
              style={styles.searchInput}
              onSubmitEditing={handleSearch}
            />
          </BlurView>
        </View>

        <View style={styles.mapContainer}>
          <AnimatedMapView style={styles.map} region={mapRegion} showsUserLocation>
            {filteredHotels.map((hotel) => (
              <Marker key={hotel.id} coordinate={hotel.coordinates} title={hotel.name} />
            ))}
          </AnimatedMapView>
        </View>

        <Animated.FlatList
          data={filteredHotels}
          horizontal
          showsHorizontalScrollIndicator={false}
          keyExtractor={(item) => item.id}
          contentContainerStyle={{ paddingHorizontal: 20 }}
          snapToInterval={CARD_WIDTH + 20}
          decelerationRate="fast"
          onScroll={Animated.event([{ nativeEvent: { contentOffset: { x: scrollX } } }], { useNativeDriver: true })}
          renderItem={({ item, index }) => <HotelCard item={item} index={index} />}
        />
      </SafeAreaView>
    </ImageBackground>
  );
}

const styles = StyleSheet.create({
  searchContainer: { marginHorizontal: 20, marginBottom: 15 },
  searchInputWrapper: { borderRadius: 20, overflow: "hidden" },
  searchInput: { height: 50, paddingHorizontal: 20, fontSize: 16, color: "#fff" },
  mapContainer: {
    width: "90%",
    height: 220,
    alignSelf: "center",
    marginBottom: 20,
    borderRadius: 25,
    overflow: "hidden",
    shadowColor: "#000",
    shadowOffset: { width: 0, height: 5 },
    shadowOpacity: 0.6,
    shadowRadius: 12,
  },
  map: { ...StyleSheet.absoluteFillObject },
  card: {
    width: CARD_WIDTH,
    height: 250,
    borderRadius: 25,
    overflow: "hidden",
    marginRight: 20,
    backgroundColor: "rgba(30,30,30,0.7)",
    shadowColor: "#000",
    shadowOffset: { width: 0, height: 10 },
    shadowOpacity: 0.5,
    shadowRadius: 15,
    elevation: 15,
  },
  image: { width: "100%", height: "100%" },
  hotelNameOverlay: { position: "absolute", bottom: 0, width: "100%", paddingVertical: 15, alignItems: "center" },
  hotelName: { color: "#fff", fontSize: 24, fontWeight: "bold", textShadowColor: "rgba(0,0,0,0.85)", textShadowOffset: { width: 0, height: 3 }, textShadowRadius: 8 },
});
